after:
    CONSTANTS c_parallel TYPE c LENGTH 1 VALUE 'P'.
{{#simulate}}
    " the simulated twin of the work (port work, variant sim): the seed of its
    " streams, and its time scale in wall millionths per simulated second
{{#seed}}
    CONSTANTS c_sim_seed TYPE i VALUE {{value}}.
{{/seed}}
{{#scale}}
    CONSTANTS c_sim_scale TYPE i VALUE {{value}}.
{{/scale}}
{{/simulate}}

{{#stages}}
{{#piles}}
{{#sim}}
    " a simulated pile's keys: the rows of its range read through port
    " {{source.name}}, keys only, sorted; none for an empty range
    CLASS-METHODS sim_keys_{{no}}
      IMPORTING it_range TYPE tt_range_{{no}}
                iv_bind TYPE string OPTIONAL
      RETURNING VALUE(rt_keys) TYPE string_table.
{{/sim}}
{{/piles}}
{{/stages}}
{{#simulate}}
    " the model hash a simulated run writes under, sim256: for sha256:, so
    " its rows never take a real run's slots and its finalise never deletes them
    CLASS-METHODS sim_hash
      IMPORTING iv_hash TYPE csequence
      RETURNING VALUE(rv_hash) TYPE zosd_l3_alert-model_hash.
    " what the doctor and resume( ) heal a run with: iv_bind when given, else
    " the run's recorded binding when it was a simulated run, else nothing
    CLASS-METHODS sim_bind
      IMPORTING iv_recorded TYPE csequence
                iv_bind TYPE string OPTIONAL
      RETURNING VALUE(rv_bind) TYPE string.
{{/simulate}}
{{#sources}}
    " puts the rows of {{table}} back after a replay: the rows kept before it

before:
    DATA ls_pile TYPE zosd_l3_pile.
{{#stages}}
{{#piles}}
    DATA lt_range_{{no}} TYPE tt_range_{{no}}.

after:
{{#simulate}}
    DATA li_work TYPE REF TO {{work_iface}}.
    DATA ls_work TYPE {{work_iface}}=>ty_pile.
    DATA lt_simkeys TYPE string_table.
{{/simulate}}
    DATA ls_pile TYPE zosd_l3_pile.
{{#stages}}
{{#piles}}
    DATA lt_range_{{no}} TYPE tt_range_{{no}}.

        rs_rule-stage_no = {{stage_no}}.
{{#sim}}
        IF li_work IS BOUND.
          rs_rule-model_hash = sim_hash( rs_rule-model_hash ).
        ENDIF.
{{/sim}}

{{#sim}}
        IF li_work IS BOUND.
          CLEAR lt_simkeys.
{{#range}}
          lt_simkeys = sim_keys_{{stage_no}}( it_range = lt_range_{{stage_no}} iv_bind = iv_bind ).
{{/range}}
          lt_found = li_work->keys( is_pile = ls_work
                                    it_keys = lt_simkeys ).
        ELSE.
{{/sim}}
          lt_keys_{{index}} = {{check_class}}=>keys( iv_date = iv_date{{#range}} it_range = lt_range_{{stage_no}}{{/range}}{{#param_args}} {{ref}} = ls_params-{{name}}{{/param_args}} ).
          LOOP AT lt_keys_{{index}} INTO ls_key_{{index}}.
            APPEND ls_key_{{index}}-low TO lt_found.
          ENDLOOP.
{{#sim}}
        ENDIF.
{{/sim}}

{{#check}}
{{#sim}}
        IF li_work IS BOUND.
          CLEAR lt_simkeys.
{{#range}}
          lt_simkeys = sim_keys_{{stage_no}}( it_range = lt_range_{{stage_no}} iv_bind = iv_bind ).
{{/range}}
          lt_alerts = li_work->check( is_pile = ls_work
                                      it_keys = lt_simkeys ).
        ELSE.
{{/sim}}
          lt_alerts = {{check_class}}=>check( iv_date{{#has_args}} = iv_date{{/has_args}}{{#range}} it_range = lt_range_{{stage_no}}{{/range}}{{#param_args}} {{ref}} = ls_params-{{name}}{{/param_args}} ).
{{#sim}}
        ENDIF.
{{/sim}}
        write( EXPORTING iv_date = iv_date
                         iv_run = iv_run
                         iv_pile = iv_pile

    DATA lv_latest TYPE zosd_l3_run-run_id.
{{#simulate}}
    DATA lv_hash TYPE zosd_l3_alert-model_hash.
{{/simulate}}

{{#simulate}}
        AND model_hash = lv_hash
{{/simulate}}
        AND check_date = iv_date
        AND run_id <> iv_run.

